"""Validate a PLAN against the protocol's structural + load requirements."""
import sys
sys.setrecursionlimit(100000)

def validate_plan(plan, n, links, caps, parts, r, p_b):
    """plan: dict trees/routes/recipes. caps: per-direction chunk capacity."""
    C = set(v for (v, rv) in parts)
    D = sum(r.values())
    trees = plan['trees']; routes = plan['routes']; recipes = plan['recipes']
    errs = []
    if len(trees) > 8192: errs.append('too many trees')
    if len(routes) > 32768: errs.append('too many routes')
    if len(recipes) > 65536: errs.append('too many recipes')
    # ---- trees
    L = {}
    per_root = {}
    for rec in trees:
        if not (isinstance(rec, list) and len(rec) == 3): errs.append('tree shape'); continue
        root, cnt, edges = rec
        if not isinstance(cnt, int) or cnt <= 0 or cnt > D: errs.append('tree count')
        if root not in C: errs.append('tree root not participant')
        per_root[root] = per_root.get(root, 0) + cnt
        es = [(e[0], e[1]) for e in edges]
        if len(es) != len(C) - 1: errs.append('tree edge count')
        if len(set(es)) != len(es): errs.append('tree dup edges')
        indeg = {}
        for (u, w) in es:
            if u not in C or w not in C or u == w: errs.append('tree edge vertices')
            indeg[w] = indeg.get(w, 0) + 1
            L[(u, w)] = L.get((u, w), 0) + cnt
        if indeg.get(root, 0) != 0: errs.append('root indeg')
        for v in C:
            if v == root: continue
            if indeg.get(v, 0) != 1: errs.append('indeg')
        # reachability
        children = {}
        for (u, w) in es: children.setdefault(u, []).append(w)
        seen = {root}; st=[root]
        while st:
            x = st.pop()
            for y in children.get(x, []):
                if y not in seen: seen.add(y); st.append(y)
        if seen != C: errs.append('not spanning')
    for v in C:
        if per_root.get(v, 0) != r[v]: errs.append('root total %r != %r' % (per_root.get(v,0), r[v]))
    # ---- recipes
    def walk_bounds(i, memo):
        """return (start, end) of recipe i, checking typing/acyclicity"""
        if i in memo: return memo[i]
        if i in walk_bounds.stack: raise ValueError('cycle')
        walk_bounds.stack.add(i)
        node = recipes[i]
        if not (isinstance(node, list) and len(node) in (3,)): raise ValueError('recipe shape')
        if node[0] == 0:
            l, d = node[1], node[2]
            if not (0 <= l < len(links)): raise ValueError('recipe link')
            u, v = links[l]
            res = (v, u) if d == 0 else (u, v)
        elif node[0] == 1:
            a, b = node[1], node[2]
            if not (isinstance(a, int) and 0 <= a < len(recipes)): raise ValueError('ref')
            if not (isinstance(b, int) and 0 <= b < len(recipes)): raise ValueError('ref')
            sa, ea = walk_bounds(a, memo)
            sb, eb = walk_bounds(b, memo)
            if ea != sb: raise ValueError('junction mismatch')
            if ea in C: raise ValueError('junction is participant')
            res = (sa, eb)
        else:
            raise ValueError('recipe tag')
        walk_bounds.stack.discard(i)
        memo[i] = res
        return res
    walk_bounds.stack = set()
    bounds = {}
    for i in range(len(recipes)):
        try:
            bounds[i] = walk_bounds(i, {})
        except ValueError as ex:
            errs.append('recipe %d: %s' % (i, ex))
            return errs
    def load_of(i, mult, acc, depth=0):
        if depth > 200: raise ValueError('deep')
        node = recipes[i]
        if node[0] == 0:
            l, d = node[1], node[2]
            acc[(l, d)] = acc.get((l, d), 0) + mult
        else:
            a, b = node[1], node[2]
            load_of(a, mult, acc, depth+1)
            load_of(b, mult, acc, depth+1)
    # ---- routes
    rsum = {}
    for rec in routes:
        if not (isinstance(rec, list) and len(rec) == 4): errs.append('route shape'); continue
        u, v, cnt, rid = rec
        if u not in C or v not in C or u == v: errs.append('route endpoints')
        if not isinstance(cnt, int) or cnt < 1 or cnt > D: errs.append('route count')
        if not (isinstance(rid, int) and 0 <= rid < len(recipes)): errs.append('route ref'); continue
        if bounds[rid] != (u, v): errs.append('route walk %r != %r' % (bounds[rid], (u, v)))
        rsum[(u, v)] = rsum.get((u, v), 0) + cnt
    for key, val in L.items():
        if rsum.get(key, 0) != val:
            errs.append('route sum %r: %r != %r' % (key, rsum.get(key,0), val))
    for key in rsum:
        if rsum[key] != L.get(key, 0):
            errs.append('extra route pair %r' % (key,))
    # ---- loads
    loads = {}
    for rec in routes:
        u, v, cnt, rid = rec
        acc = {}
        try:
            load_of(rid, cnt, acc)
        except ValueError as ex:
            errs.append('load: %s' % ex); return errs
        for k, val in acc.items():
            loads[k] = loads.get(k, 0) + val
    for l in range(len(links)):
        for d in (0, 1):
            if loads.get((l, d), 0) > caps[l]:
                errs.append('overload link %d dir %d: %d > %d' % (l, d, loads.get((l,d),0), caps[l]))
    return errs
